#!/usr/bin/env node
// CLAUDE-GENERATOR variant of the prompt ladder (NOT in the paper; a clean-subagent probe).
//
// Accounts are generated by ISOLATED Claude Opus 4.8 subagents that see ONLY the ladder's
// generator prompt (facts F + the witness's self-interest) and nothing about Feasible(F),
// U_i, the enumerated answer, or this project -- so the generator is not contaminated.
// Those accounts are stored in claude-accounts.json. THIS script only does the SAME scoring
// discipline as prompt-ladder.mjs:
//   * extraction of the causal signature is by a DIFFERENT model (Cerebras zai-glm-4.7,
//     temp 0.1) -- no self-grading;
//   * the objective is the SAME structural U_i + simulator-decided Feasible(F) from
//     grove-core.mjs; no LLM ever scores an account.
// Only extraction hits the network. Usage:
//   OPENAI_API_KEY=$(security find-generic-password -s cerebras-api -a jjz -w | cut -d, -f1) \
//     node recon/claude-ladder.mjs
import fs from 'node:fs'
import path from 'node:path'
import url from 'node:url'
import { CAST, feasibles, features, U, matchSignature } from './grove-core.mjs'

const HERE = path.dirname(url.fileURLToPath(import.meta.url))
const BASE_URL = process.env.CEREBRAS_BASE_URL || 'https://api.cerebras.ai/v1'
const KEY = (process.env.CEREBRAS_KEY || process.env.OPENAI_API_KEY || '').trim()
if (!KEY) { console.error('need a Cerebras key in CEREBRAS_KEY or OPENAI_API_KEY'); process.exit(1) }
const EXTRACTOR = 'zai-glm-4.7'   // different from the generator (Claude); mechanical parser
const EXTRACT_SYS = `Extract only what the account CLAIMS about the death. JSON: {"wielder":"Tajomaru|Masago|Takehiro|self|unclear","manner":"duel|murder|suicide|impaling|other","weapon":"longsword|dagger|unclear"}`

const sleep = (ms) => new Promise(r => setTimeout(r, ms))
async function extract(text) {
  for (let t = 0; t < 4; t++) {
    try {
      const res = await fetch(`${BASE_URL}/chat/completions`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${KEY}` },
        body: JSON.stringify({ model: EXTRACTOR, temperature: 0.1, max_tokens: 200, reasoning_effort: 'none', response_format: { type: 'json_object' },
          messages: [{ role: 'system', content: EXTRACT_SYS }, { role: 'user', content: `ACCOUNT:\n"""${text}"""` }] }),
      })
      if (res.status === 429) { await sleep(15000); continue }
      if (!res.ok) throw new Error('HTTP ' + res.status)
      const c = (await res.json()).choices?.[0]?.message?.content || ''
      return JSON.parse(c)
    } catch (e) { if (t >= 3) return null; await sleep(4000) }
  }
  return null
}

const uPct = (w, an) => Math.round(100 * U[w](features(w, an)))
// feasible optimum per witness (same deterministic tie-break as prompt-ladder.mjs)
const argmaxFeasible = (w) => feasibles.map(r => ({ r, u: U[w](features(w, r.an)) }))
  .sort((a, b) => (b.u - a.u) || a.r.sig.localeCompare(b.r.sig))[0]
const ours = {}, ourSig = {}
for (const w of CAST) { const b = argmaxFeasible(w); ours[w] = Math.round(100 * b.u); ourSig[w] = b.r.sig }

const accounts = JSON.parse(fs.readFileSync(path.join(HERE, 'claude-accounts.json'), 'utf8'))
const results = []
for (const a of accounts) {
  const claim = await extract(a.account)
  if (!claim) { results.push({ ...a, ok: false }); console.log(`${a.cond.padEnd(11)} ${a.witness.padEnd(9)}: EXTRACTION FAILED`); continue }
  const rec = matchSignature(claim, a.witness)
  const u = rec ? uPct(a.witness, rec.an) : null
  console.log(`${String(a.cond).padEnd(11)} ${a.witness.padEnd(9)}: ${String(claim.manner).padEnd(8)} by ${String(claim.wielder).padEnd(9)} w/ ${String(claim.weapon).padEnd(9)} -> ${rec ? (rec.feasible ? 'FEASIBLE' : 'REFUTED ') : 'unmatched'}  U=${u ?? '-'}`)
  results.push({ ...a, ok: true, claim, sig: rec?.sig ?? null, feasible: rec?.feasible ?? null, U: u })
}

const mode = (arr) => { const c = {}; let b = null, bn = -1; for (const x of arr) { c[x] = (c[x] || 0) + 1; if (c[x] > bn) { bn = c[x]; b = x } } return b }
const CONDS = [...new Set(accounts.map(a => a.cond))]
function condRow(cond) {
  const rows = results.filter(r => r.cond === cond && r.ok && r.feasible !== null)
  const refuted = rows.length ? rows.filter(r => !r.feasible).length / rows.length : null
  const perW = {}, sigs = []
  for (const w of CAST) {
    const rs = rows.filter(r => r.witness === w); if (!rs.length) { sigs.push(null); continue }
    const msig = mode(rs.map(r => r.sig)); const rep = rs.find(r => r.sig === msig)
    perW[w] = rep ? rep.U : null; sigs.push(msig)
  }
  return { cond, n: rows.length, refuted, U: { Tajomaru: perW.Tajomaru ?? null, Masago: perW.Masago ?? null, Takehiro: perW.Takehiro ?? null }, distinct: new Set(sigs.filter(Boolean)).size }
}
const ladder = CONDS.map(condRow)

console.log(`\n===== CLAUDE LADDER (Opus 4.8 via isolated subagents; extractor ${EXTRACTOR}, structural U_i) =====`)
console.log('rung          bandit  wife  samurai  refuted%  distinct')
const fmt = (r) => `${String(r.cond).padEnd(12)}  ${String(r.U.Tajomaru ?? '-').padStart(6)} ${String(r.U.Masago ?? '-').padStart(5)} ${String(r.U.Takehiro ?? '-').padStart(7)}  ${r.refuted == null ? '   -  ' : (100 * r.refuted).toFixed(0).padStart(5) + '%'}   ${r.distinct}`
for (const r of ladder) console.log(fmt(r))
console.log(`${'optimum'.padEnd(12)}  ${String(ours.Tajomaru).padStart(6)} ${String(ours.Masago).padStart(5)} ${String(ours.Takehiro).padStart(7)}      0%   ${new Set(Object.values(ourSig)).size}  <- feasible optimum (simulator)`)

fs.writeFileSync(path.join(HERE, 'claude-ladder-data.json'), JSON.stringify({ generatedAt: new Date().toISOString(), model: 'claude-opus-4.8 (isolated subagents)', extractor: EXTRACTOR, ladder, ours: { U: ours, sig: ourSig }, results }, null, 1))
console.log('\nwritten: recon/claude-ladder-data.json')
